// ─── File: ComputeIfAbsentTrapDemo.java ───
// Shows the computeIfAbsent trap (slow lambda holds the bin lock → threads serialize),
// then the fix (async cache + refreshAfterWrite: readers get current value, one bg refresh).
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.logging.*;

public class ComputeIfAbsentTrapDemo {
    private static final Logger log = Logger.getLogger("RATE");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        PricingService pricing = new PricingService(200);  // 200ms slow compute
        int readers = 16;

        // BROKEN: computeIfAbsent holds the bin lock during the slow lambda.
        log.info("=== BROKEN: computeIfAbsent — threads serialize on the bin lock ===");
        BrokenRateCache broken = new BrokenRateCache(pricing);
        long t0 = System.currentTimeMillis();
        runConcurrent(readers, () -> broken.getRate("USDINR"));
        long brokenMs = System.currentTimeMillis() - t0;
        log.warning(() -> readers + " readers took " + brokenMs + "ms (serialized); compute calls="
                + pricing.computeCount() + ", max blocked waiters=" + broken.maxWaiters());

        // FIXED: async cache + refreshAfterWrite — readers never block, ONE bg refresh.
        log.info("=== FIXED: AsyncLoadingCache + refreshAfterWrite — zero readers block ===");
        pricing.reset();
        FixedRateCache fixed = new FixedRateCache(pricing, 5000);
        fixed.warmUp("USDINR");                      // one initial load
        long t1 = System.currentTimeMillis();
        runConcurrent(readers, () -> fixed.getRate("USDINR"));
        long fixedMs = System.currentTimeMillis() - t1;
        log.info(() -> readers + " readers took " + fixedMs + "ms (all instant); background refreshes="
                + pricing.computeCount());
    }

    static void runConcurrent(int n, Runnable task) throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(n);
        CountDownLatch start = new CountDownLatch(1), done = new CountDownLatch(n);
        for (int i = 0; i < n; i++) pool.submit(() -> {
            try { start.await(); task.run(); } catch (InterruptedException ignored) {}
            finally { done.countDown(); }
        });
        start.countDown(); done.await(); pool.shutdown();
    }
}

// ─── source/PricingService.java (slow external compute) ───
class PricingService {
    private final long latencyMs; private final AtomicInteger count = new AtomicInteger();
    PricingService(long latencyMs) { this.latencyMs = latencyMs; }
    long computeRate(String pair) {
        count.incrementAndGet();
        try { Thread.sleep(latencyMs); } catch (InterruptedException ignored) {}  // SLOW
        return 83_00 + Math.abs(pair.hashCode() % 100);   // e.g. ~83.xx rupees
    }
    int computeCount() { return count.get(); }
    void reset() { count.set(0); }
}

// ─── broken/BrokenRateCache.java (computeIfAbsent trap) ───
class BrokenRateCache {
    private final ConcurrentHashMap<String, Long> map = new ConcurrentHashMap<>();
    private final PricingService pricing;
    private final AtomicInteger inFlight = new AtomicInteger(), maxWaiters = new AtomicInteger();
    BrokenRateCache(PricingService pricing) { this.pricing = pricing; }
    long getRate(String pair) {
        // TRAP: the slow lambda runs WHILE the bin lock is held → every thread
        // hashing to this bin serializes behind it (thundering herd, park/unpark).
        int waiting = inFlight.incrementAndGet();
        maxWaiters.accumulateAndGet(waiting, Math::max);
        try {
            return map.computeIfAbsent(pair, pricing::computeRate);  // holds bin lock through computeRate
        } finally { inFlight.decrementAndGet(); }
    }
    int maxWaiters() { return maxWaiters.get(); }
}

// ─── fixed/FixedRateCache.java (async + refreshAfterWrite, single-flight) ───
class FixedRateCache {
    private static final Logger log = Logger.getLogger("RATE");
    // Emulates Caffeine AsyncLoadingCache: value held as a volatile with computedAt.
    private volatile long value; private volatile long computedAtMs;
    private final PricingService pricing; private final long refreshMs;
    private final ExecutorService bg = Executors.newSingleThreadExecutor();
    private final AtomicBoolean refreshing = new AtomicBoolean(false);  // single-flight
    FixedRateCache(PricingService pricing, long refreshMs) { this.pricing = pricing; this.refreshMs = refreshMs; }

    void warmUp(String pair) { value = pricing.computeRate(pair); computedAtMs = System.currentTimeMillis(); }

    long getRate(String pair) {
        long now = System.currentTimeMillis();
        // Return the CURRENT value instantly — never block on compute.
        if (now - computedAtMs >= refreshMs && refreshing.compareAndSet(false, true)) {
            // Only ONE background thread recomputes; everyone else uses the current value.
            bg.submit(() -> {
                try { value = pricing.computeRate(pair); computedAtMs = System.currentTimeMillis(); }
                finally { refreshing.set(false); }
            });
        }
        return value;   // instant, non-blocking for all readers
    }
}

